// ---------------------------------------------------------------------------
// the three gates
//
// Baselines were generated by running each gate over the tree at the commit the
// gate landed and recording the existing violations, exactly as checklist §11
// prescribes (diff-only first, then ratchet the allow-list down). Every entry is
// a KNOWN legacy site with its reason — never a blanket file exemption.
// ---------------------------------------------------------------------------

func gates() []gate {
	return []gate{
		{
			id:             "Rule 16 (%w error wrapping)",
			checklistRow:   "2.2",
			probe:          "TestGate1ErrorWrapRedProof",
			escape:         errorWrapEscape,
			baselineReason: "every entry predates the gate; the `%w` codemod is its own task and this list may only shrink (the ratchet is enforced: a fixed site leaves a STALE entry that fails the gate).",
			baseline:       errorWrapBaseline,
			find:           errorWrapFind,
		},
		{
			id:             "Rule 17 (test env isolation)",
			checklistRow:   "5.2",
			probe:          "TestGate2TestEnvRedProof",
			wantTest:       true,
			scanRoots:      testRoots,
			escape:         testEnvEscape,
			baselineReason: "89 legacy sites the t.Setenv sweep left behind (devdoc/style-sweep-20260912.md) — the list is their reason, not an adjacent marker: 63 sit on os.Unsetenv (16 inside a hand-rolled Setenv/Unsetenv region, 47 a bare unset with no os.Setenv within 8 lines — 31 forcing a default/false branch in a test body, 14 the undo half written as an explicit t.Cleanup/defer, 2 a suite-wide hook reset in TestMain), because a bare t.Setenv cannot express ABSENCE; the other 26 are os.Setenv — 20 marked as a child-process handoff a bare t.Setenv would erase before the child runs, 4 a synchronous read or restore half. Annotated coverage is thin AND one-sided: 26 entries carry a marker on the offending line and 38 within +/-3 lines (43 within +/-6) — every one of the 26 on-line markers sits on an os.Setenv line and NONE on the 63 os.Unsetenv lines; a NEW os.Setenv site is the defect (measured per class: devdoc/standards-gate-accounting.md §2). The two suite-wide hook resets in TestMain were REMOVED from this list on 2026-09-12: they became testutil.PinSuiteNotifyEnv (internal/testutil/suiteenv.go), which drops the notify vars AND points GOPI_SETTINGS at an empty sandbox path, so the two entries went STALE and the ratchet moved down with them. The count is 88 from 2026-09-23 (62 os.Unsetenv + 26 os.Setenv): internal/tools/tasks_test.go's permit was retired by the same ratchet — master's aed9e482 had lengthened the file above that site without re-keying the permit, so the key named no line while the freed site read as NEW; the site is now CORRECT rather than permitted (a testutil.SnapshotEnv capture, which restores ABSENCE where a hand-rolled os.Getenv save/restore leaves \"\") and carries the visible inline env-leak-ok escape instead of a line-keyed number that rots on the next edit above it.",
			baseline:       testEnvBaseline,
			find:           testEnvFind,
		},
		{
			id:             "Rule 18 (no else after terminating if)",
			checklistRow:   "4.3",
			probe:          "TestGate3ElseAfterReturnRedProof",
			escape:         elseAfterReturnEscape,
			baselineReason: "every entry predates the gate and is behaviour-identical to the guard-clause form; the affected functions are not in this task's refactor scope.",
			baseline:       elseAfterReturnBaseline,
			find:           elseAfterReturnFind,
		},
		{
			id:             "Rule 19 (no panic outside init/main/Must*)",
			checklistRow:   "2.7",
			probe:          "TestGate4PanicRedProof",
			escape:         panicOutsideInitEscape,
			baselineReason: "no existing site: the two candidates were annotated in place (crashdump re-panic) or fall outside the predicate, so this gate lands with an EMPTY baseline — every future panic is a new violation.",
			baseline:       panicOutsideInitBaseline,
			find:           panicFind,
		},
		{
			id:             "Rule 21 (env-name constant must have a real reader)",
			checklistRow:   "1b/env",
			probe:          "TestGate6EnvReaderRedProof",
			escape:         envReaderEscape,
			baselineReason: "no existing site: an unread env hook is a hook with no consumer — it lands with an EMPTY baseline, so a new one fails on the commit that introduces it.",
			baseline:       envReaderBaseline,
			find:           envNameFind,
		},
		{
			id:             "Rule 20 (no get/is/handle prefix on an accessor)",
			checklistRow:   "1.4",
			probe:          "TestGate5AccessorPrefixRedProof",
			escape:         accessorPrefixEscape,
			baselineReason: "one site (internal/shot/x11.go handshake) carries the documented inline escape; the baseline stays empty.",
			baseline:       accessorPrefixBaseline,
			find:           accessorPrefixFind,
		},
		worktreeRootGate(),
		scratchEnvHomeGate(),
		conflictMarkerGate(),
		branchForceGate(),
		archiveMintGate(),
		removalShellGate(),
		redproofRestoreGate(),
		gitEnvGate(),
		sandboxSettingsDocGate(),
		devdocRefGate(),
	}
}

// TestStandardGates runs every gate over the tree: any new violation — or any
// stale baseline entry — fails the test. This is the gate that CI/local
// `go test ./...` picks up automatically (constraint 6).
func TestStandardGates(t *testing.T) {
	for _, g := range gates() {
		g := g
		t.Run(g.probe, func(t *testing.T) {
			hits, files := scan(t, g)
			c := classifyAll(g, hits, files)
			// Every figure on this row is COUNTED by classifyAll's one pass over
			// the hits — never derived from another column. The row used to
			// print `countHits(hits) - len(g.baseline)` as "new/gated", mixing
			// units (a HIT count minus an ENTRY count; one entry covers every
			// hit on its line) and logging a positive number on a run that
			// raised zero errors — a green gate read like a red one.
			// `new` is the class enforce() fails on: 0 on a green run.
			t.Logf("%s: %d total hits, %d baselined, %d escaped, %d new (unannotated), "+
				"%d baseline entries",
				g.id, c.total, c.baselined, c.escaped, c.unannot, len(g.baseline))
			// The invariant compares HIT counts on both sides — the classes
			// against the scan's own tally — so no column can be reintroduced as
			// a cross-channel subtraction. (len(g.baseline) is an ENTRY count and
			// deliberately outside this check: it shares no unit with a hit.)
			if c.baselined+c.escaped+c.unannot != countHits(hits) {
				t.Errorf("%s: the classes do not add up to the hit total (%d+%d+%d != %d) — "+
					"the row above would be an arithmetic lie", g.id,
					c.baselined, c.escaped, c.unannot, countHits(hits))
			}
			enforce(t, g, hits, files)
		})
	}
}

// TestStandardGateDataReport prints the counts the devdoc report quotes, and
// asserts the arithmetic the report depends on: every hit is either baselined
// (a known legacy site) or escaped inline (a reviewed site). A hit that is
// neither would fail TestStandardGates, so this test documents the split.
func TestStandardGateDataReport(t *testing.T) {
	ForgetUndecidableFormats()
	for _, g := range gates() {
		hits, files := scan(t, g)
		c := classifyAll(g, hits, files)
		t.Logf("%s (checklist %s): hits=%d baselined=%d escaped=%d NEW=%d",
			g.id, g.checklistRow, c.total, c.baselined, c.escaped, c.unannot)
		for _, e := range escapedHits(g, hits, files) {
			t.Logf("  escape: %s", e)
		}
		// THE UNDECIDABLE CHANNEL, reported rather than dropped (Rule 15). A
		// fmt.Errorf whose format string cannot be resolved statically is not a
		// violation — the verbs it holds are not knowable — but it is NOT nothing
		// either: before this channel existed the predicate returned early on it
		// and the site vanished from every number this report printed, which is
		// how this gate came to call a tree clean that stylegate reported 8
		// violations in. The count is printed unconditionally, and the sites are
		// named so a reader can decide whether one is a real defect the analyser
		// simply cannot see.
		if undecidable := UndecidableFormats(); len(undecidable) > 0 {
			t.Logf("  undecidable format strings: %d (recorded, not asserted — see gate1_fmtformat.go)",
				len(undecidable))
			for _, u := range undecidable {
				t.Logf("    undecidable: %s", u)
			}
		}
		if c.unannot != 0 {
			t.Errorf("%s: %d hit(s) are neither baselined nor escaped — TestStandardGates "+
				"fails them, so this report would be lying about a green gate", g.id, c.unannot)
		}
		if c.baselined > maxBaselineEntries {
			t.Logf("  RATCHET: %d baseline entries exceed the %d review budget — this gate "+
				"needs a codemod pass, not more entries (see devdoc/standards-gate.md)",
				c.baselined, maxBaselineEntries)
		}
	}
}

// ---------------------------------------------------------------------------
// red proofs — each gate must report a deliberately violating snippet and stay
// silent on a compliant one. Without these the gate could silently rot to a
// no-op and still show green.
// ---------------------------------------------------------------------------

// probeHits parses src and runs one gate's predicate over it.
func probeHits(t *testing.T, g gate, src string) []hit {
	t.Helper()
	fset, f := parseSource(t, "probe.go", src)
	return g.find(g, &parsed{rel: "probe.go", fset: fset, file: f, src: []byte(src)})
}

func TestGate1ErrorWrapRedProof(t *testing.T) {
	g := gates()[0]
	violating := `package p

import "fmt"

func f(err error) error { return fmt.Errorf("load config: %v", err) }
`
	if hits := probeHits(t, g, violating); len(hits) == 0 {
		t.Fatalf("RED PROOF FAILED: a %s-wrapped error was not reported — gate 1 is vacuous", "%v")
	} else if hits[0].line != 5 {
		t.Fatalf("RED PROOF: reported line %d, want 5", hits[0].line)
	}

	compliant := `package p

import "fmt"

func f(err error) error { return fmt.Errorf("load config: %w", err) }
`
	if hits := probeHits(t, g, compliant); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on a correct %%w wrap: %+v", hits)
	}

	// a %v that renders a NON-error value is formatting, not a broken chain,
	// and must not be reported (this is the gate's false-positive boundary).
	nonError := `package p

import "fmt"

func f(n int) error { return fmt.Errorf("bad count: %v", n) }
`
	if hits := probeHits(t, g, nonError); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on a non-error %%v: %+v", hits)
	}
}

func TestGate2TestEnvRedProof(t *testing.T) {
	g := gates()[1]
	violating := `package p

import (
	"os"
	"testing"
)

func TestX(t *testing.T) { os.Setenv("GOPI_X", "1") }
`
	if hits := probeHits(t, g, violating); len(hits) == 0 {
		t.Fatal("RED PROOF FAILED: os.Setenv was not reported — gate 2 is vacuous")
	} else if hits[0].line != 8 {
		t.Fatalf("RED PROOF: reported line %d, want 8", hits[0].line)
	}

	compliant := `package p

import "testing"

func TestX(t *testing.T) { t.Setenv("GOPI_X", "1") }
`
	if hits := probeHits(t, g, compliant); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on t.Setenv: %+v", hits)
	}
}

// TestGate2EnvRestoreShapeRedProof pins the SHAPE half of gate 2: the same
// os.Setenv that carries a reviewed escape reason is still a defect when the
// value written back was captured with os.Getenv, because os.Getenv cannot tell
// "unset" from "set to \"\"" — the variable that was ABSENT before the flip
// comes back set to the empty string (typically a per-test scratch-directory
// path the framework has already removed).
//
// The four negative probes are the gates' precision discipline: the predicate
// must flag the lossy capture and NOTHING else — an os.LookupEnv capture (the
// correct hand-rolled form), a constant value (nothing to restore), a capture
// from another function (a parameter, not a leak), and a value that just
// happens to share the identifier's name.
func TestGate2EnvRestoreShapeRedProof(t *testing.T) {
	g := gates()[1]
	shapeHits := func(src string) []hit {
		t.Helper()
		var out []hit
		for _, h := range probeHits(t, g, src) {
			if strings.HasPrefix(h.desc, testEnvRestoreShapePrefix) {
				out = append(out, h)
			}
		}
		return out
	}

	violating := `package p

import "os"

func flip(k, v string) {
	prev := os.Getenv("GOPI_MEMORY_DB")
	os.Setenv("GOPI_MEMORY_DB", v)
	os.Setenv("GOPI_MEMORY_DB", prev)
}
`
	hits := shapeHits(violating)
	if len(hits) == 0 {
		t.Fatal("RED PROOF FAILED: an os.Getenv-captured restore was not reported — the shape predicate is vacuous")
	}
	if hits[0].line != 8 {
		t.Fatalf("RED PROOF: reported line %d, want 8 (the write-back, not the flip)", hits[0].line)
	}

	// The reviewed correct form: presence-preserving capture. Not a hit.
	compliant := `package p

import "os"

func flip(v string) {
	prev, had := os.LookupEnv("GOPI_MEMORY_DB")
	os.Setenv("GOPI_MEMORY_DB", v)
	if had {
		os.Setenv("GOPI_MEMORY_DB", prev)
	} else {
		os.Unsetenv("GOPI_MEMORY_DB")
	}
}
`
	if got := shapeHits(compliant); len(got) != 0 {
		t.Fatalf("FALSE POSITIVE on the os.LookupEnv form: %+v", got)
	}

	// A constant value per call has nothing to restore (the table-driven case
	// the per-call-flip rule deliberately ignores).
	constant := `package p

import "os"

func flip() { os.Setenv("GOPI_MEMORY_DB", "/fixed/dead/path") }
`
	if got := shapeHits(constant); len(got) != 0 {
		t.Fatalf("FALSE POSITIVE on a constant value: %+v", got)
	}

	// A capture made in ANOTHER function is a parameter, not a leaked capture.
	elsewhere := `package p

import "os"

var prev = os.Getenv("GOPI_MEMORY_DB")

func flip() { os.Setenv("GOPI_MEMORY_DB", prev) }
`
	if got := shapeHits(elsewhere); len(got) != 0 {
		t.Fatalf("FALSE POSITIVE on a capture from another function: %+v", got)
	}

	// The capture key and the write-back key must MATCH: a value captured from
	// another variable is not a capture of the key being written.
	otherKey := `package p

import "os"

func flip(v string) {
	prev := os.Getenv("GOPI_OTHER")
	os.Setenv("GOPI_MEMORY_DB", prev)
	os.Setenv("GOPI_OTHER", v)
}
`
	if got := shapeHits(otherKey); len(got) != 0 {
		t.Fatalf("FALSE POSITIVE on a mismatched key: %+v", got)
	}
}

func TestGate3ElseAfterReturnRedProof(t *testing.T) {
	g := gates()[2]
	violating := `package p

func f(n int) int {
	if n < 0 {
		return 0
	} else {
		return n
	}
}
`
	hits := probeHits(t, g, violating)
	if len(hits) == 0 {
		t.Fatal("RED PROOF FAILED: else-after-return was not reported — gate 3 is vacuous")
	} else if hits[0].line != 6 {
		t.Fatalf("RED PROOF: reported line %d, want 6", hits[0].line)
	}

	// an else whose if-body does NOT terminate is a legitimate branch and must
	// not be reported.
	compliant := `package p

func f(n int) int {
	if n < 0 {
		n = 0
	} else {
		n = n * 2
	}
	return n
}
`
	if hits := probeHits(t, g, compliant); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on a non-terminating if: %+v", hits)
	}
}

// TestGate2ScansTheE2ESuite proves the RULE 17 scan reaches the top-level
// e2e suite, not only internal/ + cmd/. The red proof above feeds the
// PREDICATE a snippet, which would stay green even if the gate never opened a
// testsuite file — the e2e tree is exactly the kind of hole that reads as
// covered. This asserts the SCAN ROOT (testRoots) contains the suite, so
// dropping the tree fails here rather than silently un-gating it.
func TestGate2ScansTheE2ESuite(t *testing.T) {
	g := gates()[1] // Rule 17
	if !g.wantTest {
		t.Fatal("Rule 17 gate must scan _test.go files")
	}
	if !slices.Contains(g.scanRoots, e2eTestRoot) {
		t.Fatalf("Rule 17 scan roots %v do not include %q — an os.Setenv in the "+
			"top-level e2e suite would not be reported", g.scanRoots, e2eTestRoot)
	}
	root := repoRoot(t)
	got := goFilesUnder(t, root, g.scanRoots, g.wantTest)
	var e2e int
	for _, rel := range got {
		if strings.HasPrefix(rel, e2eTestRoot+"/") {
			e2e++
		}
	}
	if e2e == 0 {
		t.Fatalf("the Rule 17 scan sees no _test.go file under %s/ — the e2e suite is "+
			"outside the gate's reach (roots %v)", e2eTestRoot, g.scanRoots)
	}
	t.Logf("Rule 17 scans %d test files, %d of them under %s/", len(got), e2e, e2eTestRoot)
}

// TestEscapeMarkersWork proves the inline escape hatch is per-line and honest:
// a marked violating line is suppressed, and the marker does not leak to the
// following line.
func TestEscapeMarkersWork(t *testing.T) {
	g := gates()[0]
	marked := `package p

import "fmt"

func f(err error) error { return fmt.Errorf("a: %v", err) } // no-wrap: not inspectable upstream
`
	if hits := probeHits(t, g, marked); len(hits) != 1 {
		t.Fatalf("expected exactly one hit before escaping, got %+v", hits)
	} else if !lineHasMarker([]byte(marked), hits[0].line, errorWrapEscape) {
		t.Fatal("escape marker on the offending line was not detected — the escape hatch is broken")
	}
	unmarked := strings.Replace(marked, " // no-wrap: not inspectable upstream", "", 1)
	fset, f := parseSource(t, "probe.go", unmarked)
	hits := g.find(g, &parsed{rel: "probe.go", fset: fset, file: f, src: []byte(unmarked)})
	if len(hits) != 1 || lineHasMarker([]byte(unmarked), hits[0].line, errorWrapEscape) {
		t.Fatal("marker leaked: an unmarked line still reads as escaped")
	}
}

// TestBaselinesAreSortedAndUnique keeps the generated baseline lists reviewable:
// a duplicate entry is a copy-paste error, an unsorted one hides the site.
//
// The shape asserted is the CONTENT key (internal/sitekey) — path, normalized
// line text, ordinal — not the `file:line` spelling it replaced. The property the
// old assertion protected is kept: an entry must still be pinned to a SITE (a
// bare file would be a blanket exemption), and it is now pinned to the site's text
// as well.
func TestBaselinesAreSortedAndUnique(t *testing.T) {
	for _, g := range gates() {
		if !sort.StringsAreSorted(g.baseline) {
			t.Errorf("%s: baseline is not sorted", g.id)
		}
		seen := map[string]bool{}
		for _, b := range g.baseline {
			if seen[b] {
				t.Errorf("%s: duplicate baseline entry %s", g.id, b)
			}
			seen[b] = true
			if !sitekey.WellFormed(b) {
				t.Errorf("%s: baseline entry %q is not a site key (path, normalized line text, "+
					"ordinal) — a bare file would be a blanket exemption, and an entry without "+
					"text names no site at all. Mint it with %s, never by hand.",
					g.id, b, sitekey.KeyCreatedBy)
			}
		}
	}
}

// TestGate4PanicRedProof proves the panic gate reports an in-band panic and
// stays silent for the three shapes Google Go Style allows.
func TestGate4PanicRedProof(t *testing.T) {
	g := gateByProbe(t, "TestGate4PanicRedProof")
	violating := `package p

func loadConfig(path string) {
	if path == "" {
		panic("empty config path")
	}
}
`
	hits := probeHits(t, g, violating)
	if len(hits) == 0 {
		t.Fatal("RED PROOF FAILED: an in-band panic was not reported — gate 4 is vacuous")
	} else if hits[0].line != 3 {
		t.Fatalf("RED PROOF: reported func line %d, want 3", hits[0].line)
	}

	allowed := `package p

func init()   { panic("bad build tag") }
func main()   { panic("unrecoverable") }
func MustOpen(p string) int { panic("unopenable: " + p) }
`
	if hits := probeHits(t, g, allowed); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on init/main/Must*: %+v", hits)
	}

	// a closure inside a Main-named helper is NOT main: the name must match, and
	// the escape has to be explicit.
	closure := `package p

func setup() {
	f := func() { panic("inner") }
	f()
}
`
	if hits := probeHits(t, g, closure); len(hits) == 0 {
		t.Fatal("a panic in a closure inside a non-init/main/Must func must be reported")
	}

	// the Must* exemption is name-based, not argument-based: a Must func still
	// takes arguments and must stay exempt (checklist 1.4's accessor scope does
	// not apply to this gate).
	mustArgs := `package p

func MustDiv(a, b int) int { panic("div by zero") }
`
	if hits := probeHits(t, g, mustArgs); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on Must*(args): %+v", hits)
	}
}

// TestGate5AccessorPrefixRedProof proves the accessor-prefix gate reports
// getFoo/isFoo/handleFoo and stays silent on the shapes it deliberately excludes.
func TestGate5AccessorPrefixRedProof(t *testing.T) {
	g := gateByProbe(t, "TestGate5AccessorPrefixRedProof")
	violating := `package p

type c struct{ name string }

func (x c) getName() string { return x.name }
func (x c) isValid() bool   { return x.name != "" }
func (x c) handleEvent()    {}
`
	if hits := probeHits(t, g, violating); len(hits) != 3 {
		t.Fatalf("RED PROOF FAILED: want 3 prefixed accessors, got %+v", hits)
	}

	// deliberately excluded shapes — each is a legitimate name, and each is why
	// the gate's false-positive count is zero:
	excluded := `package p

type c struct{ name string }

func (x c) Name() string        { return x.name }
func (x c) Get(k string) string { return k } // takes an argument: a command, not an accessor
func island() int               { return 1 } // package function: not a method
func (x c) islandOf() int       { return 1 } // lowercase after the prefix
`
	if hits := probeHits(t, g, excluded); len(hits) != 0 {
		t.Fatalf("FALSE POSITIVE on an excluded shape: %+v", hits)
	}
}

// TestEscapeMarkerAboveSite proves the escape window: a marker in the contiguous
// comment block directly above the reported line escapes it, while a marker that
// is NOT contiguous does not (otherwise one marker could silence a whole file).
func TestEscapeMarkerAboveSite(t *testing.T) {
	g := gateByProbe(t, "TestGate4PanicRedProof")
	above := `package p

// helper does work.
//
// panic-ok: re-panic from recover — the crash path must keep crashing.
func helper(x any) {
	panic(x)
}
`
	if hits := probeHits(t, g, above); len(hits) != 1 {
		t.Fatalf("expected one hit to escape, got %+v", hits)
	} else if !markerOn(linesAbove([]byte(above), hits[0].line), panicOutsideInitEscape) {
		t.Fatal("a contiguous comment-block escape was not detected")
	}

	// A panic probe is reported at its FUNC line, so the detached-marker case
	// cannot be simulated with a statement above it — use the else gate, which
	// reports at the exact `} else {` line, to prove non-contiguity is enforced.
	eg := gateByProbe(t, "TestGate3ElseAfterReturnRedProof")
	lines := strings.Split(above, "\n")
	elseProbe := "package p\n\n" + strings.Join(lines[3:4], "\n") + "\nfunc f(n int) int {\n\tif n < 0 {\n\t\treturn 0\n\t} else {\n\t\treturn n\n\t}\n}\n"
	fset, f := parseSource(t, "probe.go", elseProbe)
	ehits := eg.find(eg, &parsed{rel: "probe.go", fset: fset, file: f, src: []byte(elseProbe)})
	if len(ehits) != 1 {
		t.Fatalf("else probe: expected 1 hit, got %+v", ehits)
	}
	if markerOn(linesAbove([]byte(elseProbe), ehits[0].line), elseAfterReturnEscape) {
		t.Fatal("a marker separated from the reported line by code escaped it — the escape window is too wide")
	}
}

// TestBaselineReasonsAreCarried asserts every gate declares an allow-list reason
// and that each gate's baseline fits the review budget. A baseline nobody can
// read is not an allow-list — the gate reads green while the tree stays dirty
// (that is the failure mode this whole file exists to avoid).
func TestBaselineReasonsAreCarried(t *testing.T) {
	for _, g := range gates() {
		if strings.TrimSpace(g.baselineReason) == "" {
			t.Errorf("%s: no baseline reason — an unexplained allow-list is a silent permission", g.id)
		}
		// The ceiling is a FLOOR-of-last-resort: hitting it means the gate has
		// stopped ratcheting, and the next move is the codemod, not a bigger
		// number.
		if len(g.baseline) >= maxBaselineEntries {
			t.Errorf("%s: %d baseline entries hit the %d ceiling — this gate must be shrunk "+
				"(codemod), never extended (see devdoc/standards-gate.md)",
				g.id, len(g.baseline), maxBaselineEntries)
		}
		// A baseline that is not allowed to grow is only half a ratchet: the
		// scheduled shrinking is enforced by the codemod task, and this test
		// records the ceiling so a reviewer can see the debt.
		if len(g.baseline) == 0 && g.escape == "" {
			t.Errorf("%s: no baseline AND no escape hatch declared", g.id)
		}
		rendered := baselineOf(g).render()
		for _, want := range []string{"// " + g.baselineReason, probeRunPrefix + g.probePath()} {
			if !strings.Contains(rendered, want) {
				t.Errorf("%s: rendered baseline block is missing %q — the allow-list must carry its "+
					"reason and its PUBLISHED enforcement command next to the entries (the "+
					"tree-reading subtest path, never the bare red-proof name)", g.id, want)
			}
		}
	}
}

// baselineLine used to render `rel:line` for a generated list. It is DELETED
// rather than rewritten, because a key is no longer derived from a line number
// and this package has no business minting one: the ONE writer of baseline
// entries is the generator (internal/standards/testdata/baseline-rekey.go), which
// calls internal/sitekey.Key — the same function the gate's own hits are keyed
// with, so the two halves cannot disagree about a site's identity.

// TestGate6EnvReaderRedProof is the negative test the acceptance criteria
// require: a snippet carrying an unread env hook must be REPORTED (and the
// reported hit must carry the reviewed-escape marker the framework consults), a
// snippet whose constant reaches os.Getenv must be SILENT, and a following
// statement's identifiers must never be mistaken for readers.
func TestGate6EnvReaderRedProof(t *testing.T) {
	g := gateByProbe(t, "TestGate6EnvReaderRedProof")

	// RED: an unread hook is reported. The hit carries this gate's inline
	// escape marker, which classify() checks in the comment block above the
	// hit line — that is the reviewed exemption mechanism.
	unread := `package p

import "os"

const lonelyEnv = "GOPI_LONELY_HOOK"
const lonelyEnvName = "GOPI_LONELY_HOOK_NAME"
const notEnvValue = "just a string"

func use() { _ = lonelyEnv + lonelyEnvName + notEnvValue }
`
	hits := probeHits(t, g, unread)
	if len(hits) != 2 {
		t.Fatalf("red proof: got %d hits, want 2 (the two unread env constants, not the plain string): %+v",
			len(hits), hits)
	}

	// GREEN: os.Getenv(<constant>) is a real reader.
	read := `package p

import "os"

const readEnv = "GOPI_READ_HOOK"

func use() string { return os.Getenv(readEnv) }
`
	if got := probeHits(t, g, read); len(got) != 0 {
		t.Fatalf("read proof: os.Getenv(constant) must count as a real reader, got %+v", got)
	}

	// GREEN: a reader through a helper funnel (boolEnvTrue) counts too — the
	// scaffold must not depend on the stdlib os.* spelling.
	funnel := `package p

const funnelEnv = "GOPI_FUNNEL_HOOK"

func use() bool { return boolEnvTrue(funnelEnv) }
`
	if got := probeHits(t, g, funnel); len(got) != 0 {
		t.Fatalf("helper proof: boolEnvTrue(constant) must count as a real reader, got %+v", got)
	}

	// GREEN: a FOLLOWING statement's identifiers are not readers (the paren
	// scan is multi-line exact, not a fixed lookback).
	adjacent := `package p

import "os"

const adjacentEnv = "GOPI_ADJACENT_HOOK"

func use() {
	_ = os.Getenv("GOPI_OTHER_HOOK")
	_ = adjacentEnv
}
`
	if got := probeHits(t, g, adjacent); got[0].rel == "" || len(got) != 1 {
		t.Fatalf("adjacency proof: want exactly one hit (the constant is not inside the call), got %+v", got)
	}

	// The escape mechanism itself: the marker must suppress the hit. classify()
	// reads linesAbove(), which starts at the hit line and continues up the
	// contiguous comment block — so the marker is accepted in EITHER placement:
	// a TRAILING comment on the hit line (the shape every live site in this tree
	// carries, e.g. internal/config/config.go's MergeTickRetiredEnvName) or the
	// last line of the comment block above it. The two arms below pin one
	// placement each, because a doc promising a placement the code rejects sends
	// the next reader to rewrite a live site for nothing.
	escapedSrc := "package p\n\n// " + strings.TrimPrefix(g.escape, "// ") +
		" the reader is generated\nconst escapedEnv = \"GOPI_ESCAPED_HOOK\"\n"
	p := &parsed{rel: "probe.go", src: []byte(escapedSrc)}
	fset, f := parseSource(t, "probe.go", escapedSrc)
	p.fset, p.file = fset, f
	if got := g.find(g, p); len(got) != 1 {
		t.Fatalf("escape fixture must produce one raw hit to classify, got %+v", got)
	}
	if class := classify(g, g.find(g, p)[0], p); class != classEscaped {
		t.Fatalf("escape proof: the %q marker above the hit must classify as escaped, got %v",
			g.escape, class)
	}

	// The marker also suppresses on the hit line ITSELF, where it is a TRAILING
	// comment — which is the shape every live site in this tree carries
	// (`const MergeTickRetiredEnvName = "GOPI_MERGE_TICK_MIN" // env-reader-exempt: …`,
	// internal/config/config.go). Both placements are accepted by ONE rule:
	// classify() reads linesAbove(), which starts at the hit line and continues
	// up the contiguous comment block, so a trailing marker and an above marker
	// are the same mechanism. This arm pins that, because a doc that promised a
	// placement the code rejects would send the next reader to rewrite a live
	// site for nothing.
	trailingSrc := "package p\n\nconst trailingEnv = \"GOPI_TRAILING_HOOK\" " +
		g.escape + " the reader is generated\n"
	tp := &parsed{rel: "probe.go", src: []byte(trailingSrc)}
	tfset, tf := parseSource(t, "probe.go", trailingSrc)
	tp.fset, tp.file = tfset, tf
	trailingHits := g.find(g, tp)
	if len(trailingHits) != 1 {
		t.Fatalf("trailing-marker fixture must produce one raw hit to classify, got %+v", trailingHits)
	}
	if class := classify(g, trailingHits[0], tp); class != classEscaped {
		t.Fatalf("trailing escape proof: a %q marker on the hit line itself must classify as "+
			"escaped (the live sites carry it there), got %v", g.escape, class)
	}
}

// TestGate6EnvReaderEscapedSiteDoesNotFailTheExhaustiveArm is the planted
// proof that the exhaustive arm's verdict is the CLASSIFIER's, not the raw hit
// count.
//
// The measured defect this pins: the exhaustive arm asserted `len(hits) != 0`
// while its own log printed `hits=1 baselined=0 escaped=1 NEW=0` — so the
// documented escape was inert on the only surface that scans the real tree, and
// the two ways out were both forbidden (delete a constant the rule requires, or
// add the baseline entry this gate exists to prevent).
//
// Both directions are asserted, because a predicate that excused everything
// would pass the first half and destroy the gate:
//
//	escaped+unmarked fixture  → escaped=1 NEW=0 → the arm's verdict is ""
//	the SAME source unescaped → escaped=0 NEW=1 → the arm's verdict names it
//
// The strip leg is a real mutation of the fixture bytes (the marker text
// removed), never a second hand-written source, so the two readings differ by
// exactly the marker and nothing else.
func TestGate6EnvReaderEscapedSiteDoesNotFailTheExhaustiveArm(t *testing.T) {
	g := gateByProbe(t, "TestGate6EnvReaderRedProof")
	if g.escape == "" {
		t.Fatal("this proof is meaningless for a gate with no escape marker")
	}
	// ONE constant in a namespace the pattern recognises, with no reader.
	escapedSrc := "package p\n\nconst plantedEnv = \"GOPI_PLANTED_HOOK\" " + g.escape +
		" planted: this fixture exists to prove the escape is honoured\n"
	unescapedSrc := strings.Replace(escapedSrc, g.escape+" planted: this fixture exists to prove the escape is honoured", "", 1)
	if unescapedSrc == escapedSrc {
		t.Fatalf("the strip leg removed nothing — the marker text is not in the fixture as written")
	}

	planted := func(src, name string) classCount {
		t.Helper()
		p := &parsed{rel: name, src: []byte(src)}
		fset, f := parseSource(t, name, src)
		p.fset, p.file = fset, f
		hits := g.find(g, p)
		if len(hits) != 1 {
			t.Fatalf("%s: fixture must produce exactly one raw hit, got %+v", name, hits)
		}
		stamp(hits, map[string]*parsed{name: p})
		return classifyAll(g, hits, map[string]*parsed{name: p})
	}

	escaped := planted(escapedSrc, "escaped_probe.go")
	t.Logf("escaped fixture:  %s", classCountLine(g, escaped))
	if escaped.total != 1 || escaped.escaped != 1 || escaped.unannot != 0 {
		t.Fatalf("an escaped, unread constant must classify as escaped (total=1 escaped=1 NEW=0), got %s",
			classCountLine(g, escaped))
	}
	if msg := envReaderUnexcusedFailure(g, escaped); msg != "" {
		t.Fatalf("an escaped hit must NOT fail the exhaustive arm, but its verdict was %q\n"+
			"  (this is the defect: a verdict that reads the raw hit count makes the escape inert)",
			msg)
	}

	unescaped := planted(unescapedSrc, "unescaped_probe.go")
	t.Logf("unescaped fixture: %s", classCountLine(g, unescaped))
	if unescaped.total != 1 || unescaped.escaped != 0 || unescaped.unannot != 1 {
		t.Fatalf("the same constant WITHOUT the marker must classify as unannotated, got %s",
			classCountLine(g, unescaped))
	}
	msg := envReaderUnexcusedFailure(g, unescaped)
	if msg == "" {
		t.Fatal("an unmarked unread hook must still fail the exhaustive arm — the verdict excused it, " +
			"so the gate no longer guards anything")
	}
	// The failure must be actionable: it names the count, the marker and the
	// site's class, not merely "1 problem".
	for _, want := range []string{"NEW=1", g.escape, g.id} {
		if !strings.Contains(msg, want) {
			t.Fatalf("the unexcused verdict must quote %q so a reader can act on it, got %q", want, msg)
		}
	}
}

// TestGate6EnvReaderFindsTheRealTree is the exhaustive half: run the gate's
// predicate over the WHOLE production tree and require that the hook this gate
// was written for is gone. A gate that is green because its reader index is
// EMPTY (a broken scan) would pass the red proof above and still be blind —
// this test fails in that case.
func TestGate6EnvReaderFindsTheRealTree(t *testing.T) {
	g := gateByProbe(t, "TestGate6EnvReaderRedProof")
	index := envReaders()
	if len(index.byID) == 0 {
		t.Fatal("the reader index is EMPTY — the production scan is blind")
	}
	// ScratchGCIntervalEnvName is deliberately the ALIAS case: its own name has
	// no reader, but it aliases the one definition (scratch.GCIntervalEnvName),
	// whose readers are real — the gate must resolve through the alias, or it
	// would demand a duplicate env read.
	for _, must := range []string{"GCIntervalEnvName", "TempDirEnvName"} {
		if len(index.sites(must)) == 0 {
			t.Fatalf("the reader index found no site for %s — the scan is blind (index size %d)",
				must, len(index.byID))
		}
	}
	aliasFile := parseRepoFile(t, repoRoot(t), scratchAliasFile)
	aliases := aliasesOf(aliasFile)
	if aliases[scratchAliasConst] != scratchAliasTarget {
		t.Fatalf("%s must still resolve %s → %s (alias map: %v)",
			scratchAliasFile, scratchAliasConst, scratchAliasTarget, aliases)
	}
	if !resolvedByReader(scratchAliasConst, index, nil, aliases, 1) {
		t.Fatalf("alias resolution failed: %s → %s reaches a real reader, so the gate must accept it",
			scratchAliasConst, scratchAliasTarget)
	}
	hits, files := scan(t, g)
	c := classifyAll(g, hits, files)
	t.Logf("%s", classCountLine(g, c))
	// THE VERDICT IS THE CLASSIFIER'S, NEVER THE RAW HIT COUNT. A scan hit is
	// only a CANDIDATE: classify() buckets it as baselined (a recorded legacy
	// site), escaped (the reviewed inline marker) or unannotated (a real
	// violation), and enforce() `continue`s past the first two. An arm asserting
	// `len(hits) != 0` therefore makes every PERMITTED site unreleasable — the
	// escape was recognised everywhere except at the one surface that scans the
	// real tree, which printed `hits=1 baselined=0 escaped=1 NEW=0` before
	// failing, leaving only two exits and both forbidden: delete
	// internal/config/config.go's MergeTickRetiredEnvName (the rule requires the
	// spelling to be nameable) or add the baseline entry this gate exists to
	// prevent. envReaderUnexcusedFailure is the ONE definition of the verdict and
	// it quotes the full accounting, so a reader can reconcile it with the row
	// above; TestGate6EnvReaderPlantedFailureDrivesTheCount and
	// TestGate6EnvReaderEscapedSiteDoesNotFailTheExhaustiveArm pin both
	// directions, so a swap back onto a raw count turns this red instead of
	// leaving a green that measures nothing.
	if msg := envReaderUnexcusedFailure(g, c); msg != "" {
		t.Fatalf("%s\n  the unexcused hits: %+v", msg, hits)
	}
	// Non-vacuity: a tree carrying no PERMITTED site at all would make the
	// verdict above unreachable-by-construction, so the escape this gate
	// documents would never be exercised on the real tree.
	if c.escaped+c.baselined == 0 {
		t.Fatalf("%s: the real tree carries no escaped and no baselined hit, so this arm "+
			"never exercises the escape mechanism it documents — the scan is blind (%s)",
			g.id, classCountLine(g, c))
	}
}

// gateByProbe returns the gate registered under a probe name (a red-proof test
// must run the REAL gate, not a copy — a copy can pass while the gate rots).
func gateByProbe(t *testing.T, probe string) gate {
	t.Helper()
	for _, g := range gates() {
		if g.probe == probe {
			return g
		}
	}
	t.Fatalf("no gate registered with probe %q", probe)
	return gate{}
}

func probeClassify(t *testing.T, g gate, src string) classCount {
	t.Helper()
	fset, f := parseSource(t, "probe.go", src)
	p := &parsed{rel: "probe.go", fset: fset, file: f, src: []byte(src)}
	return classifyAll(g, g.find(g, p), map[string]*parsed{"probe.go": p})
}

// TestGate6EnvReaderPlantedFailureDrivesTheCount is the planted arm for the
// predicate above: it proves the count TestGate6EnvReaderFindsTheRealTree now
// keys on is NON-VACUOUS — it still FAILS on a hit with no exemption, and it
// clears only when the SAME hit carries the gate's own marker, at the
// documented spelling, on the offending line itself.
//
// It drives the real path (the gate's own find → classifyAll → classify), never
// a copy of the predicate: a future change that quietly neutralises the escape
// mechanism, or that swaps the verdict back onto a raw count, turns this arm
// red instead of leaving a green that measures nothing.
func TestGate6EnvReaderPlantedFailureDrivesTheCount(t *testing.T) {
	g := gateByProbe(t, "TestGate6EnvReaderRedProof")
	marker := g.escape
	if marker == "" {
		t.Fatal("this gate carries no inline escape marker — the planted arm has nothing to plant")
	}

	// PLANTED VIOLATION: an env constant with no reader and NO exemption — the
	// same declaration shape as the real site that exposed this bug, minus its
	// marker. It must land in the count the verdict keys on.
	unmarked := "package p\n\nconst plantedEnv = \"GOPI_PLANTED_HOOK\"\n"
	red := probeClassify(t, g, unmarked)
	if red.unannot != 1 {
		t.Fatalf("planted arm: an unexempted hook must land in the count the verdict keys on "+
			"(unannot=1), got %+v — a pass here would make this arm VACUOUS", red)
	}
	if red.escaped != 0 {
		t.Fatalf("planted arm: nothing is escaped in the unmarked fixture, got escaped=%d (%+v)",
			red.escaped, red)
	}

	// THE SAME HIT, EXEMPTED: the marker at its documented spelling, on the
	// offending line itself — the shape internal/config/config.go:1260 uses for
	// the retirement-refusal constant this gate's verdict was failing on. Only
	// the CLASS may move; the site must still be SEEN.
	marked := "package p\n\nconst plantedEnv = \"GOPI_PLANTED_HOOK\" " + marker +
		" planted by this arm — no reader by design\n"
	green := probeClassify(t, g, marked)
	if green.unannot != 0 {
		t.Fatalf("planted arm: with the %q marker present the hook must leave the failing count, "+
			"got unannot=%d (%+v)", marker, green.unannot, green)
	}
	if green.escaped != 1 {
		t.Fatalf("planted arm: the exempted hook must be COUNTED as escaped so it stays visible in "+
			"the data report, got escaped=%d (%+v)", green.escaped, green)
	}
	if red.total != 1 || green.total != 1 {
		t.Fatalf("planted arm: both fixtures must produce exactly one raw scan hit — the marker "+
			"changes the CLASS, never whether the site is seen; got unmarked=%d marked=%d",
			red.total, green.total)
	}
}
